a<-commandArgs(TRUE);p<-a[1];s<-read.csv(file.path(p,'summary.csv'));labels<-c('young 48 fixed','old 48 fixed','young 48 staggered','old 48 staggered');z<-s[s$type=='gate_effect_on_threshold' & s$metric=='population1000' & s$label %in% labels,];z<-z[match(labels,z$label),];stopifnot(nrow(z)==4,!anyNA(z$mean),all(z$n>1));se<-(z$upper-z$lower)/(2*qt(.975,z$n-1));z$p_two_sided<-2*pt(-abs(z$mean/se),df=z$n-1);z$p_holm_four<-p.adjust(z$p_two_sided,'holm');write.csv(z,file.path(p,'primary-multiplicity.csv'),row.names=FALSE);print(z[,c('label','mean','lower','upper','p_two_sided','p_holm_four')],row.names=FALSE)
